.xt-root::-webkit-scrollbar, .xt-text::-webkit-scrollbar { width: 0 !important; display: none !important; }

/* ================= 1. 根容器 (透明背景) ================= */
.xt-root {
    width: 360px !important; height: 600px !important;
    background: transparent !important; 
    position: relative !important; margin: 20px auto !important;
    overflow: hidden !important; pointer-events: auto !important;
}

/* 背景波点装饰 (低饱和度灰粉) */
.xt-root::before, .xt-root::after {
    content: '' !important; position: absolute !important;
    background-image: radial-gradient(#e8dcdc 30%, transparent 30%) !important;
    background-size: 12px 12px !important;
    z-index: 1 !important;
}
.xt-root::before {
    top: 20px !important; right: 40px !important; width: 60px !important; height: 60px !important;
    border-radius: 50% !important; transform: rotate(15deg) !important;
}
.xt-root::after {
    bottom: 30px !important; left: 30px !important; width: 50px !important; height: 50px !important;
    border-radius: 50% !important;
}

/* ================= 2. 主纸张 ================= */
.xt-text:nth-of-type(1) {
    position: absolute !important; top: 60px !important; left: 25px !important;
    width: 310px !important; height: 460px !important;
    background-color: #ffffff !important;
    /* 笔记本横线 (淡粉色 #f5ebeb) */
    background-image: repeating-linear-gradient(transparent, transparent 23px, #f5ebeb 23px, #f5ebeb 24px) !important;
    background-position: 0 30px !important;
    border-radius: 8px !important;
    transform: rotate(-4deg) !important;
    box-shadow: -6px 12px 20px rgba(216, 202, 202, 0.3) !important;
    z-index: 2 !important;
}
/* 左侧打孔效果 */
.xt-text:nth-of-type(1)::before {
    content: '' !important; position: absolute !important; top: 0 !important; left: -8px !important;
    width: 16px !important; height: 100% !important;
    background-image: radial-gradient(circle at 8px 12px, transparent 5px, #ffffff 5.5px) !important;
    background-size: 16px 24px !important;
    background-position: 0 10px !important;
    filter: drop-shadow(-2px 0px 1px rgba(216, 202, 202, 0.4)) !important;
}

/* ================= 3. 左上角胶带 ================= */
.xt-text:nth-of-type(2) {
    position: absolute !important; top: 65px !important; left: 35px !important;
    width: 80px !important; height: 25px !important;
    background-color: rgba(245, 235, 235, 0.95) !important;
    background-image: radial-gradient(circle, #d8caca 1.5px, transparent 2px) !important;
    background-size: 10px 10px !important;
    transform: rotate(-15deg) !important;
    box-shadow: 1px 2px 4px rgba(216, 202, 202, 0.3) !important;
    z-index: 5 !important;
}

/* ================= 4. 右上角标题网格纸条 ================= */
