    background-image: 
        repeating-linear-gradient(0deg, transparent, transparent 9px, #f5ebeb 9px, #f5ebeb 10px),
        repeating-linear-gradient(90deg, transparent, transparent 9px, #f5ebeb 9px, #f5ebeb 10px) !important;
