_theme.customCss:
/* 0. 彻底重置 */
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { margin: 0 !important; padding: 0 !important; background: transparent !important; border: none !important; display: block !important; box-shadow: none !important; white-space: pre-wrap !important; outline: none !important; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif !important; }
.xt-root::-webkit-scrollbar, .xt-text::-webkit-scrollbar { width: 0 !important; display: none !important; }

/* ================= 1. 根容器 (透明背景) ================= */
.xt-root {
    width: 360px !important; height: 600px !important;
    background: transparent !important; 
    position: relative !important; margin: 20px auto !important;
    overflow: hidden !important; pointer-events: auto !important;
}

/* 背景波点装饰 (低饱和淡灰棕) */
.xt-root::before, .xt-root::after {
    content: '' !important; position: absolute !important;
    background-image: radial-gradient(#e8dfd8 30%, transparent 30%) !important;
    background-size: 12px 12px !important;
    z-index: 1 !important;
}
.xt-root::before {
    top: 20px !important; right: 40px !important; width: 60px !important; height: 60px !important;
    border-radius: 50% !important; transform: rotate(15deg) !important;
}
.xt-root::after {
    bottom: 30px !important; left: 30px !important; width: 50px !important; height: 50px !important;
    border-radius: 50% !important;
}

/* ================= 2. 主纸张 ================= */
.xt-text:nth-of-type(1) {
    position: absolute !important; top: 60px !important; left: 25px !important;
    width: 310px !important; height: 460px !important;
    background-color: #ffffff !important;
    /* 笔记本横线 (极淡的奶茶色) */
    background-image: repeating-linear-gradient(transparent, transparent 23px, #f0e8e0 23px, #f0e8e0 24px) !important;
    background-position: 0 30px !important;
    border-radius: 8px !important;
    transform: rotate(-4deg) !important;
    box-shadow: -6px 12px 20px rgba(160, 140, 130, 0.12) !important;
    z-index: 2 !important;
}
/* 左侧打孔效果 */
.xt-text:nth-of-type(1)::before {
    content: '' !important; position: absolute !important; top: 0 !important; left: -8px !important;
    width: 16px !important; height: 100% !important;
    background-image: radial-gradient(circle at 8px 12px, transparent 5px, #ffffff 5.5px) !important;
    background-size: 16px 24px !important;
    background-position: 0 10px !important;
    filter: drop-shadow(-2px 0px 1px rgba(160, 140, 130, 0.08)) !important;
}

/* ================= 3. 左上角胶带 ================= */
.xt-text:nth-of-type(2) {
    position: absolute !important; top: 65px !important; left: 35px !important;
    width: 80px !important; height: 25px !important;
    background-color: rgba(245, 238, 232, 0.95) !important; 
    background-image: radial-gradient(circle, #c8b8a8 1.5px, transparent 2px) !important;
    background-size: 10px 10px !important;
    transform: rotate(-15deg) !important;
    box-shadow: 1px 2px 4px rgba(160, 140, 130, 0.15) !important;
    z-index: 5 !important;
}

/* ================= 4. 右上角标题网格纸条 ================= */
.xt-text:nth-of-type(3) {
    position: absolute !important; top: 65px !important; right: 20px !important;
    width: 190px !important; height: 50px !important;
    background-color: #ffffff !important;
    background-image: 
        repeating-linear-gradient(0deg, transparent, transparent 9px, #e8dfd8 9px, #e8dfd8 10px),
        repeating-linear-gradient(90deg, transparent, transparent 9px, #e8dfd8 9px, #e8dfd8 10px) !important;
    transform: rotate(3deg) !important;
    box-shadow: 2px 4px 8px rgba(160, 140, 130, 0.1) !important;
    z-index: 4 !important;
}
.xt-text:nth-of-type(3)::before {
    content: '' !important; position: absolute !important; top: -6px !important; left: 0 !important;
    width: 100% !important; height: 12px !important;
    background-image: radial-gradient(circle at 8px 6px, transparent 3px, #ffffff 3.5px) !important;
    background-size: 16px 12px !important;
}

/* ================= 5. 标题文字 ================= */
.xt-text:nth-of-type(4) {
    position: absolute !important; top: 70px !important; right: 95px !important;
    font-family: 'Impact', 'Arial Black', sans-serif !important;
    font-size: 22px !important; color: #b09880 !important; 
    transform: rotate(3deg) !important;
    letter-spacing: 1px !important;
    z-index: 5 !important;
}
.xt-text:nth-of-type(5) {
    position: absolute !important; top: 100px !important; right: 35px !important;
    font-size: 10px !important; color: #c0b0a0 !important;
